import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Button,
  Container,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Chip,
  IconButton,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider,
  Badge,
  TextField,
  InputAdornment,
  Alert,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Rating,
} from "@mui/material";

import {
  Menu as MenuIcon,
  Restaurant,
  ShoppingCart,
  ReceiptLong,
  RateReview,
  Person,
  Logout,
  Search,
  Add,
  Remove,
  Home,
} from "@mui/icons-material";

const categories = [
  "All",
  "Breakfast",
  "Lunch",
  "Snacks",
  "Beverages",
  "Dessert",
];

const UserDashboard = ({ user, onLogout }) => {
  const [orders, setOrders] = useState([]);
  const [loadingOrders, setLoadingOrders] = useState(false);

  // =========================
  // REVIEW STATE
  // =========================
  const [reviews, setReviews] = useState([]);
  const [loadingReviews, setLoadingReviews] = useState(false);

  const [reviewDialogOpen, setReviewDialogOpen] =
    useState(false);

  const [selectedOrder, setSelectedOrder] =
    useState(null);

  const [selectedFood, setSelectedFood] =
    useState(null);

  const [selectedRating, setSelectedRating] =
    useState(0);

  const [reviewComment, setReviewComment] =
    useState("");

  const [submittingReview, setSubmittingReview] =
    useState(false);

  const [orderMessage, setOrderMessage] =
    useState("");

  const [error, setError] = useState("");
  // =========================
  // LOAD MENU
  // =========================
  const loadMenu = async () => {
    try {
      setLoadingMenu(true);

      const response = await axios.get("/api/menu");

      const items = Array.isArray(response.data)
        ? response.data
        : response.data.menuItems || [];

      setMenuItems(items);
    } catch (err) {
      console.error("Error loading menu:", err);

      setError(
        err.response?.data?.message ||
        "Unable to load menu."
      );
    } finally {
      setLoadingMenu(false);
    }
  };

  // =========================
  // LOAD USER ORDERS
  // =========================
  const loadOrders = async () => {
    try {
      setLoadingOrders(true);
      setError("");

      const token = localStorage.getItem("token");

      if (!token) {
        setError(
          "Your login session has expired. Please login again."
        );
        return;
      }

      const response = await axios.get(
        "/api/orders/my",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const apiOrders = Array.isArray(response.data)
        ? response.data
        : response.data.orders || [];

      /*
        Backend now returns:

        {
          _id,
          orderNumber,
          items: [
            {
              menuItemId,
              name,
              price,
              quantity,
              subtotal,
              image
            }
          ],
          totalAmount,
          status
        }

        Existing UI expects:

        itemName
        quantity
        price

        So we convert the new backend structure
        without changing the existing UI.
      */

      const myOrders = apiOrders.map((order) => {
        const totalQuantity = (order.items || []).reduce(
          (total, item) => total + item.quantity,
          0
        );

        return {
          ...order,

          itemName: (order.items || [])
            .map(
              (item) =>
                `${item.name} × ${item.quantity}`
            )
            .join(", "),

          quantity: totalQuantity,

          price:
            totalQuantity > 0
              ? order.totalAmount / totalQuantity
              : 0,
        };
      });

      setOrders(myOrders);
    } catch (err) {
      console.error("Error loading orders:", err);

      setError(
        err.response?.data?.message ||
        "Unable to load your orders."
      );
    } finally {
      setLoadingOrders(false);
    }
  };
  // =========================
  // LOAD MY REVIEWS
  // =========================
  const loadReviews = async () => {
    try {
      setLoadingReviews(true);

      const token = localStorage.getItem("token");

      if (!token) {
        return;
      }

      const response = await axios.get(
        "/api/reviews/my",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setReviews(
        response.data?.reviews || []
      );
    } catch (err) {
      console.error(
        "Error loading reviews:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to load reviews."
      );
    } finally {
      setLoadingReviews(false);
    }
  };


  // =========================
  // CHECK WHETHER FOOD IS ALREADY REVIEWED
  // =========================
  const isFoodReviewed = (
    orderId,
    menuItemId
  ) => {
    return reviews.some(
      (review) =>
        review.orderId?._id === orderId &&
        review.menuItemId?._id === menuItemId
    );
  };


  // =========================
  // OPEN REVIEW DIALOG
  // =========================
  const openReviewDialog = (
    order,
    food
  ) => {
    setSelectedOrder(order);
    setSelectedFood(food);

    setSelectedRating(0);
    setReviewComment("");

    setError("");

    setReviewDialogOpen(true);
  };


  // =========================
  // CLOSE REVIEW DIALOG
  // =========================
  const closeReviewDialog = () => {
    setReviewDialogOpen(false);

    setSelectedOrder(null);
    setSelectedFood(null);

    setSelectedRating(0);
    setReviewComment("");
  };


  // =========================
  // SUBMIT REVIEW
  // =========================
  const submitReview = async () => {
    if (!selectedOrder || !selectedFood) {
      setError(
        "Please select a food item."
      );
      return;
    }

    if (selectedRating < 1) {
      setError(
        "Please select a rating from 1 to 5 stars."
      );
      return;
    }

    try {
      setSubmittingReview(true);
      setError("");
      setOrderMessage("");

      const token =
        localStorage.getItem("token");

      if (!token) {
        setError(
          "Your login session has expired. Please login again."
        );
        return;
      }

      await axios.post(
        "/api/reviews",
        {
          orderId: selectedOrder._id,

          menuItemId:
            selectedFood.menuItemId,

          rating: selectedRating,

          comment:
            reviewComment.trim(),
        },
        {
          headers: {
            Authorization:
              `Bearer ${token}`,
          },
        }
      );

      setOrderMessage(
        "Review submitted successfully!"
      );

      closeReviewDialog();

      await loadReviews();
    } catch (err) {
      console.error(
        "Submit review error:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to submit review."
      );
    } finally {
      setSubmittingReview(false);
    }
  };

  // =========================
  // INITIAL LOAD
  // =========================
  useEffect(() => {
    loadMenu();
    loadOrders();
    loadReviews();

  }, []);

  // =========================
  // FILTER MENU
  // =========================
  const filteredMenu = useMemo(() => {
    const normalizeSearch = (value) => {
      const text = value
        .trim()
        .toLowerCase();

      const corrections = {
        spicey: "spicy",
        spciey: "spicy",
        spciy: "spicy",
        cakes: "cake",
        sweets: "sweet",
        drinks: "drink",
        beverages: "drink",
        snacks: "snack",
        desserts: "dessert",
      };

      return corrections[text] || text;
    };

    const searchText = normalizeSearch(search);

    // Related search terms
    const searchAliases = {
      spicy: [
        "spicy",
        "hot",
        "masala",
        "chilli",
        "chili",
        "pepper",
        "spiced",
      ],

      sweet: [
        "sweet",
        "dessert",
        "cake",
        "chocolate",
        "ice cream",
        "gulab",
        "pastry",
      ],

      cake: [
        "cake",
        "dessert",
        "chocolate",
        "sweet",
        "pastry",
      ],

      drink: [
        "drink",
        "beverage",
        "tea",
        "coffee",
        "juice",
        "lassi",
        "milkshake",
        "shake",
        "soft drink",
      ],

      snack: [
        "snack",
        "samosa",
        "pakora",
        "puff",
        "sandwich",
        "fried",
      ],

      breakfast: [
        "breakfast",
        "dosa",
        "idli",
        "vada",
        "upma",
        "poha",
        "puri",
      ],

      lunch: [
        "lunch",
        "biryani",
        "rice",
        "meal",
        "thali",
        "curry",
      ],
    };

    return menuItems.filter((item) => {
      const itemName = (
        item.name || ""
      ).toLowerCase();

      const itemCategory = (
        item.category || ""
      ).toLowerCase();

      const itemDescription = (
        item.description || ""
      ).toLowerCase();

      const itemKeywords = Array.isArray(
        item.keywords
      )
        ? item.keywords
          .join(" ")
          .toLowerCase()
        : "";

      const searchableText = `
      ${itemName}
      ${itemCategory}
      ${itemDescription}
      ${itemKeywords}
    `.toLowerCase();

      // Direct search
      let matchesSearch =
        searchText === "" ||
        searchableText.includes(searchText);

      // Related/semantic-style search
      if (
        searchText &&
        searchAliases[searchText]
      ) {
        matchesSearch =
          searchAliases[searchText].some(
            (keyword) =>
              searchableText.includes(keyword)
          );
      }

      // Category filter
      const matchesCategory =
        category === "All" ||
        item.category === category;

      return (
        matchesSearch &&
        matchesCategory
      );
    });
  }, [menuItems, search, category]);
  // =========================
  // ADD TO CART
  // =========================
  const addToCart = (item) => {
    setCart((previousCart) => {
      const existing = previousCart.find(
        (cartItem) => cartItem.name === item.name
      );

      if (existing) {
        return previousCart.map((cartItem) =>
          cartItem.name === item.name
            ? {
              ...cartItem,
              quantity: cartItem.quantity + 1,
            }
            : cartItem
        );
      }

      return [
        ...previousCart,
        {
          ...item,
          quantity: 1,
        },
      ];
    });
  };

  // =========================
  // INCREASE QUANTITY
  // =========================
  const increaseQuantity = (name) => {
    setCart((previousCart) =>
      previousCart.map((item) =>
        item.name === name
          ? {
            ...item,
            quantity: item.quantity + 1,
          }
          : item
      )
    );
  };

  // =========================
  // DECREASE QUANTITY
  // =========================
  const decreaseQuantity = (name) => {
    setCart((previousCart) =>
      previousCart
        .map((item) =>
          item.name === name
            ? {
              ...item,
              quantity: item.quantity - 1,
            }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  // =========================
  // CART COUNT
  // =========================
  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  // =========================
  // CART TOTAL
  // =========================
  const cartTotal = cart.reduce(
    (total, item) =>
      total + item.price * item.quantity,
    0
  );

  // =========================
  // PLACE ORDER
  // =========================
  const placeOrder = async () => {
    if (cart.length === 0) {
      setError("Your cart is empty.");
      return;
    }

    try {
      setError("");
      setOrderMessage("");

      const token = localStorage.getItem("token");

      if (!token) {
        setError(
          "Your login session has expired. Please login again."
        );
        return;
      }

      const response = await axios.post(
        "/api/orders",
        {
          items: cart.map((item) => ({
            menuItemId: item._id,
            quantity: item.quantity,
          })),

          paymentMethod: "Cash",

          specialRequests: "",
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setCart([]);

      const tokenNumber =
        response.data?.order?.orderNumber ||
        response.data?.orderNumber ||
        "Generated";

      setOrderMessage(
        `Order placed successfully! Your Token: ${tokenNumber}`
      );

      await loadOrders();

      setActivePage("orders");
    } catch (err) {
      console.error("Order error:", err);

      setError(
        err.response?.data?.message ||
        "Unable to place order."
      );
