              <ListItemText primary="Profile" />
            </ListItemButton>

            <Divider />

            <ListItemButton
              onClick={handleLogout}
            >
              <ListItemIcon>
                <Logout color="error" />
              </ListItemIcon>

              <ListItemText
                primary="Logout"
                sx={{
                  color: "error.main",
                }}
              />
            </ListItemButton>
          </List>
        </Box>
      </Drawer>

      <Container
        maxWidth="xl"
        sx={{
          py: 4,
        }}
      >
        {orderMessage && (
          <Alert
            severity="success"
            sx={{ mb: 3 }}
          >
            {orderMessage}
          </Alert>
        )}

        {error && (
          <Alert
            severity="error"
            sx={{ mb: 3 }}
          >
            {error}
          </Alert>
        )}

        {renderPage()}
      </Container>
    </Box>
  );
};

export default UserDashboard;
